package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
)

func probe(raw string) {
	dec := json.NewDecoder(bytes.NewReader([]byte(raw)))
	tok, err := dec.Token()
	fmt.Printf("input=%q\n  first token=%#v err=%v\n", raw, tok, err)
	for {
		t, e := dec.Token()
		if e != nil {
			fmt.Printf("  next err=%v (io.EOF=%v)\n", e, e == io.EOF)
			break
		}
		fmt.Printf("  token=%#v\n", t)
	}
}

func main() {
	for _, s := range []string{
		"\x0b{\"a\":1}",
		"{\"a\":1}\x0b",
		"{\"a\":1}\x0c",
		"{\"a\":1} ",
		"{\"a\":1}　",
		"{\"a\":1}{\"b\":2}",
		"{\"a\":1}  ",
		"{\"a\" :1}",
		"{\"a\"　:1}",
		"{\"a\":1\x0b}",
		"x{\"a\":1}",
		"{\"a\":1}x",
		"{\"a\":1} []",
		"{\"a\":\"x\x0by\"}",
	} {
		probe(s)
	}
}
EOF
