			okLine + " \n" + // line 5: fail — no-break space after the object
			`{"timestamp":"2026-01-02T00:00:00Z","action":` +
				`"mid\u000Bx",` + // legal: VT expressed as a JSON escape inside action
				`"note":` + `"　kept　"` + "}\n" + // line 6: ok — ideographic spaces are string content
			`{"timestamp":"2026-01-02T00:00:00Z","action":"a",` + "\x0c" + `"x":1}` + "\n" + // line 7: fail — form feed between members
